/** Resolve a public/ path against Vite's base so the site works under a sub-path (e.g. GitHub Pages). */
export const asset = (path: string) => import.meta.env.BASE_URL.replace(/\/$/, "") + path

/** 600px variant of a product image (generated by scripts/make-thumbs.mjs). */
export const thumb = (src: string) => src.replace(/(?<!-600)\.webp$/, "-600.webp")

/** srcset for product imagery: 600px thumbnail + full-size original. */
export const productSrcSet = (src: string) => `${thumb(src)} 600w, ${src} 1200w`
